class Coureur:
    def __init__(self, nom, fatigue):
        self.nom = nom
        self.fatigue = fatigue

    def courir(self, distance):
        self.fatigue = self.fatigue + (distance * 2)

    def est_en_forme(self):
        if self.fatigue < 50:
            return True
        else:
            return False

# Test du programme
c1 = Coureur("Alice", 10)
c2 = Coureur("Bob", 45)

c1.courir(15)
c2.courir(5)

print(f"{c1.nom} est en forme?", c1.est_en_forme())
print(f"{c2.nom} est en forme?", c2.est_en_forme())
